-- =================================================================
-- AlfaComp: Официальный список из всех 162 товаров с точными ценами
-- =================================================================

-- 1. Гарантируем наличие всех категорий
ON CONFLICT (name) DO UPDATE SET sort_order = EXCLUDED.sort_order;

-- 2. Очищаем таблицу товаров
TRUNCATE TABLE public.products RESTART IDENTITY;

-- 3. Вставляем все 162 товара

-- 4. Корректируем последовательность id
SELECT setval(pg_get_serial_sequence('public.products', 'id'), (SELECT MAX(id) FROM public.products));
